SELECT jsonb_agg(jsonb_build_object('id_filiado',p.id_origem,'id_conta',c.id_conta,'status',c.status,'documento',c.documento,'documento_pendente',c.documento_pendente,'email',c.email_principal,'logo_path',p.logo_path,'vouchers',(SELECT count(*) FROM estudo.primeiro_acesso_convites x JOIN estudo.vouchers v ON v.id=x.voucher_id WHERE x.id_conta=c.id_conta AND v.status IN ('READY','REDEEMED')),'eventos',(SELECT count(*) FROM tb_conta_eventos e WHERE e.id_conta=c.id_conta AND e.status='ATIVO')) ORDER BY p.id_origem)::text payload FROM tb_contas c JOIN tb_conta_perfis_publicos p USING(id_conta) WHERE p.origem='ABRACEO'